using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // Get all shipments (dispatchers see all, customers see only theirs)
        group.MapGet("/", async (ApplicationDbContext db, UserManager<ApplicationUser> userManager, HttpContext ctx) =>
        {
            var user = await userManager.GetUserAsync(ctx.User);
            if (user is null) return Results.Unauthorized();

            var isDispatcher = await userManager.IsInRoleAsync(user, "Dispatcher");

            var query = isDispatcher
                ? db.Shipments.AsQueryable()
                : db.Shipments.Where(s => s.CustomerId == user.Id);

            var shipments = await query.OrderByDescending(s => s.CreatedAt).ToListAsync();
            return Results.Ok(shipments);
        });

        // Get single shipment
        group.MapGet("/{id:int}", async (int id, ApplicationDbContext db, UserManager<ApplicationUser> userManager, HttpContext ctx) =>
        {
            var user = await userManager.GetUserAsync(ctx.User);
            if (user is null) return Results.Unauthorized();

            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            var isDispatcher = await userManager.IsInRoleAsync(user, "Dispatcher");
            if (!isDispatcher && shipment.CustomerId != user.Id)
                return Results.Forbid();

            return Results.Ok(shipment);
        });

        // Track by tracking number (no auth required)
        app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            if (shipment is null) return Results.NotFound();
            return Results.Ok(new
            {
                shipment.TrackingNumber,
                shipment.Origin,
                shipment.Destination,
                shipment.Status,
                shipment.EstimatedDelivery,
                shipment.ActualDelivery,
                shipment.CreatedAt
            });
        });

        // Create shipment (dispatchers only)
        group.MapPost("/", async (Shipment shipment, ApplicationDbContext db, UserManager<ApplicationUser> userManager, HttpContext ctx) =>
        {
            var user = await userManager.GetUserAsync(ctx.User);
            if (user is null) return Results.Unauthorized();

            var isDispatcher = await userManager.IsInRoleAsync(user, "Dispatcher");
            if (!isDispatcher) return Results.Forbid();

            shipment.CreatedAt = DateTime.UtcNow;
            if (string.IsNullOrEmpty(shipment.TrackingNumber))
                shipment.TrackingNumber = GenerateTrackingNumber();

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"/api/shipments/{shipment.Id}", shipment);
        });

        // Update shipment status (dispatchers only)
        group.MapPut("/{id:int}/status", async (int id, UpdateStatusRequest req, ApplicationDbContext db, UserManager<ApplicationUser> userManager, HttpContext ctx) =>
        {
            var user = await userManager.GetUserAsync(ctx.User);
            if (user is null) return Results.Unauthorized();

            var isDispatcher = await userManager.IsInRoleAsync(user, "Dispatcher");
            if (!isDispatcher) return Results.Forbid();

            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = req.Status;
            if (req.Notes is not null) shipment.Notes = req.Notes;
            if (req.Status == ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok(shipment);
        });
    }

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(100000, 999999)}";
    }
}

public record UpdateStatusRequest(ShipmentStatus Status, string? Notes);

