@page "/shipments"
@attribute [Authorize]
@rendermode InteractiveAuto
@inject ShipmentService ShipmentService

<PageTitle>Shipments</PageTitle>

<h1>📦 Shipments</h1>

<div class="mb-3 d-flex gap-2">
    <input type="text" class="form-control" placeholder="Filter by destination..."
           @bind="filterText" @bind:event="oninput" />
    <select class="form-select w-auto" @bind="statusFilter">
        <option value="">All Statuses</option>
        @foreach (var status in Enum.GetValues<ShipmentStatus>())
        {
            <option value="@status">@status</option>
        }
    </select>
    <button class="btn btn-outline-secondary" @onclick="LoadShipments">
        🔄 Refresh
    </button>
</div>

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (FilteredShipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Customer</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><code>@shipment.TrackingNumber</code></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td><span class="badge @GetStatusBadge(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                        <td>@shipment.CustomerName</td>
                        <td>
                            <button class="btn btn-sm btn-outline-primary" @onclick="() => SelectShipment(shipment)">
                                Details
                            </button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@if (selectedShipment is not null)
{
    <div class="card mt-3">
        <div class="card-header d-flex justify-content-between">
            <strong>Shipment Details: @selectedShipment.TrackingNumber</strong>
            <button class="btn-close" @onclick="() => selectedShipment = null"></button>
        </div>
        <div class="card-body">
            <dl class="row">
                <dt class="col-sm-3">Origin</dt>
                <dd class="col-sm-9">@selectedShipment.Origin</dd>
                <dt class="col-sm-3">Destination</dt>
                <dd class="col-sm-9">@selectedShipment.Destination</dd>
                <dt class="col-sm-3">Status</dt>
                <dd class="col-sm-9">@selectedShipment.Status</dd>
