<PageTitle>Create Shipment</PageTitle>

<h1>📋 Create New Shipment</h1>

<div class="row mt-4">
    <div class="col-md-8">
        <EditForm Model="shipment" OnValidSubmit="HandleSubmit" FormName="CreateShipment">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label class="form-label">Origin</label>
                <InputText class="form-control" @bind-Value="shipment.Origin" placeholder="e.g., New York, NY" />
                <ValidationMessage For="() => shipment.Origin" />
            </div>

            <div class="mb-3">
                <label class="form-label">Destination</label>
                <InputText class="form-control" @bind-Value="shipment.Destination" placeholder="e.g., Los Angeles, CA" />
                <ValidationMessage For="() => shipment.Destination" />
            </div>

            <div class="mb-3">
                <label class="form-label">Customer ID</label>
                <InputText class="form-control" @bind-Value="shipment.CustomerId" placeholder="Customer user ID" />
                <ValidationMessage For="() => shipment.CustomerId" />
            </div>

            <div class="mb-3">
                <label class="form-label">Customer Name</label>
                <InputText class="form-control" @bind-Value="shipment.CustomerName" placeholder="Customer display name" />
            </div>

            <div class="mb-3">
                <label class="form-label">Estimated Delivery</label>
                <InputDate class="form-control" @bind-Value="estimatedDelivery" />
            </div>

            <div class="mb-3">
                <label class="form-label">Notes</label>
                <InputTextArea class="form-control" @bind-Value="shipment.Notes" rows="3" />
            </div>

            @if (!string.IsNullOrEmpty(errorMessage))
            {
                <div class="alert alert-danger">@errorMessage</div>
            }

            @if (created)
            {
                <div class="alert alert-success">
                    Shipment created! Tracking #: <strong>@createdTracking</strong>
                </div>
            }

            <button type="submit" class="btn btn-primary" disabled="@submitting">
                @if (submitting)
                {
                    <span class="spinner-border spinner-border-sm"></span>
                }
                Create Shipment
            </button>
        </EditForm>
    </div>
</div>

@code {
    private ShipmentDto shipment = new();
    private DateTime? estimatedDelivery = DateTime.Today.AddDays(5);
    private bool submitting;
    private bool created;
    private string createdTracking = "";
    private string errorMessage = "";

    private async Task HandleSubmit()
    {
        submitting = true;
        errorMessage = "";
        created = false;

        shipment.EstimatedDelivery = estimatedDelivery;

        var result = await ShipmentService.CreateShipmentAsync(shipment);
        if (result is not null)
        {
            created = true;
            createdTracking = result.TrackingNumber;
            shipment = new();
            estimatedDelivery = DateTime.Today.AddDays(5);
        }
        else
        {
            errorMessage = "Failed to create shipment. Check that all fields are valid.";
        }

        submitting = false;
    }
}
