            <div class="mb-3">
                <label class="form-label">Notes</label>
                <InputTextArea class="form-control" @bind-Value="shipment.Notes" rows="3" />
            </div>

            @if (!string.IsNullOrEmpty(errorMessage))
            {
                <div class="alert alert-danger">@errorMessage</div>
            }

            @if (created)
            {
                <div class="alert alert-success">
                    Shipment created! Tracking #: <strong>@createdTracking</strong>
                </div>
            }

            <button type="submit" class="btn btn-primary" disabled="@submitting">
                @if (submitting)
                {
                    <span class="spinner-border spinner-border-sm"></span>
                }
                Create Shipment
            </button>
        </EditForm>
    </div>
</div>

@code {
    private ShipmentDto shipment = new();
    private DateTime? estimatedDelivery = DateTime.Today.AddDays(5);
    private bool submitting;
    private bool created;
    private string createdTracking = "";
    private string errorMessage = "";

    private async Task HandleSubmit()
    {
        submitting = true;
        errorMessage = "";
        created = false;

        shipment.EstimatedDelivery = estimatedDelivery;

        var result = await ShipmentService.CreateShipmentAsync(shipment);
        if (result is not null)
        {
            created = true;
            createdTracking = result.TrackingNumber;
            shipment = new();
            estimatedDelivery = DateTime.Today.AddDays(5);
        }
        else
        {
            errorMessage = "Failed to create shipment. Check that all fields are valid.";
        }

        submitting = false;
    }
}

